from collections import deque
def components(g,color):
 seen=set(); comps=[]
 for r in range(18):
  for c in range(18):
   if g[r][c]==color and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); cc=[]
    while q:
     y,x=q.pop();cc.append((y,x))
     for z in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
      yy,xx=z
      if 0<=yy<18 and 0<=xx<18 and g[yy][xx]==color and z not in seen: seen.add(z);q.append(z)
    comps.append(cc)
 return comps
